-- Business: A hardening pass for a project where the earlier migrations were ALREADY applied. It is
-- Business: idempotent and safe to run at any time, on fresh or existing data.
-- Business: Two things are repaired:
-- Business:   1. The request-code counter/function is removed. Codes are random now (generated by the Worker),
-- Business:      and while they existed in `public` they were callable by anyone with the public anon key:
-- Business:      they disclosed how many jobs exist and let a stranger advance the counter until customers
-- Business:      could no longer track their own repairs.
-- Business:   2. Any seeded demo staff credential is neutralised. Supabase Auth owns sign-in; a row whose
-- Business:      password is the published `sudhar-dev` must never be usable, in any environment.
-- Technical: Every statement is guarded, so this file is safe on a project missing parts of the schema.

-- 1. Remove the request-code RPC (and its counter) if a previous deploy created them.
do $$
begin
  if exists (
    select 1
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname = 'next_request_sequence'
  ) then
    execute 'drop function public.next_request_sequence()';
  end if;
end $$;

drop sequence if exists public.request_code_seq;

-- 2. Keep the technician counter, but make it reachable ONLY by the Worker's service_role.
do $$
begin
  if exists (
    select 1
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname = 'next_technician_code'
  ) then
    execute 'revoke all on function public.next_technician_code() from public';
    execute 'revoke all on function public.next_technician_code() from anon, authenticated';
    execute 'grant execute on function public.next_technician_code() to service_role';
  end if;
end $$;

do $$
begin
  if exists (
    select 1
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relname = 'technician_code_seq' and c.relkind = 'S'
  ) then
    execute 'revoke all on sequence public.technician_code_seq from public';
    execute 'revoke all on sequence public.technician_code_seq from anon, authenticated';
    execute 'grant usage, select, update on sequence public.technician_code_seq to service_role';
  end if;
end $$;

-- 3. Turn every known demo secret into an unmatchable tombstone. The shape stays `sha256$salt$hex` so the
--    verifier still parses it, but no password can hash to a random digest.
do $$
begin
  if to_regclass('public.staff_accounts') is not null then
    update public.staff_accounts
       set secret = 'sha256$disabled$' || md5(random()::text) || md5(random()::text)
     where identifier in ('admin', 'bikash', 'ramesh')
       and secret not like 'sha256$disabled$%';
  end if;
end $$;
